-- Course catalogue labels only. Existing certificates and course slugs are immutable here.
DO $update_course_names$
DECLARE
 catalogue jsonb := $names$[{"slug":"swiety-mikolaj","old_title_pl":"Uprawnienia Świętego Mikołaja — kurs świąteczny","title_pl":"Wizyta Świętego Mikołaja — kurs świąteczny","title_en":"Organising a Safe and Welcoming Santa Visit","certificate_pl":"Wizyta Świętego Mikołaja — kurs świąteczny","certificate_en":"Organising a Safe and Welcoming Santa Visit","description_pl":"Scenariusz wizyty Świętego Mikołaja, rozmowa z dziećmi i organizacja świątecznego wydarzenia. Bezpłatny kurs w konwencji zabawy."},{"slug":"autocad-skroty","old_title_pl":"AutoCAD — wszystkie najważniejsze skróty i komendy","title_pl":"AutoCAD — skróty i komendy w praktyce","title_en":"AutoCAD Shortcuts and Commands in Practice","certificate_pl":"AutoCAD — skróty i komendy w praktyce","certificate_en":"AutoCAD Shortcuts and Commands in Practice","description_pl":"Ściąga komend i skrótów AutoCAD: rysowanie, modyfikacja, warstwy, precyzja i wydruk rysunku."},{"slug":"ekonomia-domowa-bez-dlugow","old_title_pl":"Ekonomia domowa — wybory, które chronią przed długami","title_pl":"Ekonomia domowa — budżet, wydatki i zadłużenie","title_en":"Household Budgeting, Spending and Debt","certificate_pl":"Świadome zarządzanie budżetem i ryzykiem zadłużenia","certificate_en":"Household Budgeting and Debt-Risk Awareness","description_pl":"Zaplanuj domowe pieniądze, rozpoznaj ukryte koszty, porównaj kredyty i rachunki oraz przygotuj plan na trudniejsze miesiące — bez wstydu i nierealnych obietnic."},{"slug":"kryzys-po-40-bez-dlugow","old_title_pl":"Kryzys po czterdziestce — jak nie wpaść w długi","title_pl":"Kryzys po czterdziestce — finanse w okresie zmian","title_en":"Managing Finances During Midlife Changes","certificate_pl":"Świadome wybory finansowe i życiowe po czterdziestce","certificate_en":"Financial and Life Choices After Forty","description_pl":"Gdy po czterdziestce pojawia się potrzeba wielkiej zmiany, naucz się spokojnie policzyć koszty, zatrzymać impulsy i podjąć decyzję bez niepotrzebnego zadłużenia."},{"slug":"sitarz","old_title_pl":"Sitarz — sztuka ręcznej produkcji sit","title_pl":"Sitarstwo od podstaw — ręczne wykonywanie sit","title_en":"Traditional Sieve Making Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Sitarstwo od podstaw — ręczne wykonywanie sit","certificate_en":"Traditional Sieve Making Fundamentals","description_pl":"Poznaj dawne sita, dobór oczek i budowę drewnianej obręczy. Na prostym modelu rozdzielisz frakcje, wyjaśnisz przyczynę usterki i przygotujesz kartę odbioru."},{"slug":"snycerz","old_title_pl":"Snycerz — ornament i rzeźba w drewnie","title_pl":"Snycerstwo od podstaw — ornament i rzeźba w drewnie","title_en":"Woodcarving Fundamentals: Ornament and Relief","certificate_pl":"Ukończenie kursu teoretycznego: Snycerstwo od podstaw — ornament i rzeźba w drewnie","certificate_en":"Woodcarving Fundamentals: Ornament and Relief","description_pl":"Rozpoznaj ornament, kierunek włókien i rolę dłut. Zaprojektuj relief, zbuduj bezpieczną makietę i opracuj kartę oględzin drewnianego detalu."},{"slug":"szewc-tradycja","old_title_pl":"Szewc — uratuj i napraw stare buty","title_pl":"Podstawy szewstwa — ocena i naprawa obuwia","title_en":"Shoe Repair Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Podstawy szewstwa — ocena i naprawa obuwia","certificate_en":"Shoe Repair Fundamentals","description_pl":"Poznaj budowę obuwia, właściwości skóry, tkanin i materiałów spodowych. Przygotuj diagnozę trzech uszkodzeń oraz kosztorys bezpiecznej naprawy."},{"slug":"tkacz-reczny","old_title_pl":"Tkacz ręczny — krosno i dawne tkaniny","title_pl":"Tkactwo ręczne od podstaw — krosno i dawne tkaniny","title_en":"Handweaving Fundamentals: Looms and Traditional Textiles","certificate_pl":"Ukończenie kursu teoretycznego: Tkactwo ręczne od podstaw — krosno i dawne tkaniny","certificate_en":"Handweaving Fundamentals: Looms and Traditional Textiles","description_pl":"Poznaj osnowę, wątek i pracę krosna. Wykonaj papierowe próbki splotu, policz zmianę wymiarów i przygotuj projekt tkaniny z kartą jakości."},{"slug":"woznica","old_title_pl":"Woźnica — dawna sztuka powożenia","title_pl":"Powożenie zaprzęgiem — podstawy teoretyczne","title_en":"Horse-Drawn Carriage Driving: Theory Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Powożenie zaprzęgiem — podstawy teoretyczne","certificate_en":"Horse-Drawn Carriage Driving: Theory Fundamentals","description_pl":"Poznaj historyczne pojazdy zaprzęgowe, funkcje uprzęży i zasady dobrostanu konia. Zbuduj mapę elementów i przeanalizuj decyzje na makiecie bez pracy z koniem."},{"slug":"zdun-tradycja","old_title_pl":"Zdun — piece kaflowe i mistrzowie ciepła","title_pl":"Zduństwo od podstaw — budowa i działanie pieców kaflowych","title_en":"Traditional Tiled Stoves and Masonry Heating Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Zduństwo od podstaw — budowa i działanie pieców kaflowych","certificate_en":"Traditional Tiled Stoves and Masonry Heating Fundamentals","description_pl":"Rozpoznaj kafle, palenisko, wymianę ciepła i drogę spalin. Na schematach przećwicz ocenę objawów, zgłoszenie zagrożenia i kartę przeglądu bez rozpalania pieca."},{"slug":"zecer","old_title_pl":"Zecer — skład gazet przed komputerem","title_pl":"Zecerstwo od podstaw — ręczny skład drukarski","title_en":"Hand Typesetting Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Zecerstwo od podstaw — ręczny skład drukarski","certificate_en":"Hand Typesetting Fundamentals","description_pl":"Poznaj ręczny skład, kasztę i wierszownik. Ułóż papierową kolumnę, przeprowadź korektę odbitki i rozpoznaj zagrożenia historycznego stanowiska."},{"slug":"zegarmistrz-tradycja","old_title_pl":"Zegarmistrz — serce mechanicznego zegarka","title_pl":"Zegarmistrzostwo od podstaw — mechanizmy zegarków","title_en":"Mechanical Watchmaking Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Zegarmistrzostwo od podstaw — mechanizmy zegarków","certificate_en":"Mechanical Watchmaking Fundamentals","description_pl":"Rozpoznaj źródło energii, przekładnię, regulator i wychwyt zegara mechanicznego. Na modelu policz odchyłkę i przygotuj kartę diagnostyczną bez otwierania mechanizmu."},{"slug":"wyjdz-z-toksycznego-zwiazku","old_title_pl":"Wyjdź z toksycznego związku i nie daj się manipulować","title_pl":"Trudna relacja — granice, bezpieczeństwo i wsparcie","title_en":"Boundaries, Safety and Support in Difficult Relationships","certificate_pl":"Rozpoznawanie manipulacji i bezpieczne granice w relacjach","certificate_en":"Recognising Manipulation and Setting Safe Boundaries","description_pl":"Rozpoznawaj kontrolę i manipulację, odzyskuj własne granice i przygotuj bezpieczny plan dalszych kroków. Bez zawstydzania i bez presji na decyzję."},{"slug":"pomagaj-dziecku-w-lekcjach","old_title_pl":"Bądź dobrym nauczycielem swojego dziecka — prace domowe bez kłótni","title_pl":"Jak wspierać dziecko w nauce i odrabianiu lekcji","title_en":"Supporting Your Child with Learning and Homework","certificate_pl":"Ukończenie prywatnego kursu: Jak wspierać dziecko w nauce i odrabianiu lekcji","certificate_en":"Supporting Your Child with Learning and Homework","description_pl":"Pomagaj dziecku myśleć i samodzielnie rozwiązywać zadania, nie odrabiając lekcji za nie. Przyjazny plan także dla dziecka, które łatwo się rozprasza."},{"slug":"wsparcie-adhd","old_title_pl":"Opieka i wsparcie osób z ADHD","title_pl":"Codzienne wsparcie osób z ADHD","title_en":"Everyday Support for People with ADHD","certificate_pl":"Codzienne wsparcie osób z ADHD","certificate_en":"Everyday Support for People with ADHD","description_pl":"Zrozum codzienne wyzwania ADHD, buduj proste rutyny, wspierającą komunikację i dobre otoczenie — bez diagnozowania."},{"slug":"excel-skroty","old_title_pl":"Excel — wszystkie najważniejsze skróty klawiszowe","title_pl":"Excel — skróty klawiszowe w praktyce","title_en":"Excel Keyboard Shortcuts in Practice","certificate_pl":"Excel — skróty klawiszowe w praktyce","certificate_en":"Excel Keyboard Shortcuts in Practice","description_pl":"Praktyczna ściąga skrótów Excel dla Windows: poruszanie, tabele, formuły, formatowanie, filtrowanie i analiza."},{"slug":"opieka-seniorzy","old_title_pl":"Opieka nad osobami starszymi","title_pl":"Codzienne wsparcie osób starszych","title_en":"Supporting Older Adults in Daily Life","certificate_pl":"Codzienne wsparcie osób starszych","certificate_en":"Supporting Older Adults in Daily Life","description_pl":"Kurs o codziennej pomocy seniorowi, rozmowie, rutynie i granicach odpowiedzialności. Omówiono zasady reagowania na trudne sytuacje. Kurs nie nadaje kwalifikacji opiekuna medycznego."},{"slug":"bednarz","old_title_pl":"Bednarz — beczki i drewniane naczynia","title_pl":"Bednarstwo od podstaw — beczki i drewniane naczynia","title_en":"Coopering Fundamentals: Barrels and Wooden Vessels","certificate_pl":"Ukończenie kursu teoretycznego: Bednarstwo od podstaw — beczki i drewniane naczynia","certificate_en":"Coopering Fundamentals: Barrels and Wooden Vessels","description_pl":"16 lekcji o bednarstwie od podstaw: budowa beczki i materiałoznawstwo, narzędzia i ich konserwacja, rysunek techniczny i geometria klepek, przygotowanie i gięcie, wręga i denko, szczelność, higiena, opalanie, kosztorys, kontrola jakości oraz projekt końcowy. Kurs edukacyjny, nie nadaje kwalifikacji zawodowych; wymaga nadzorowanej praktyki warsztatowej."},{"slug":"garncarz-tradycja","old_title_pl":"Garncarz — glina i koło garncarskie","title_pl":"Garncarstwo od podstaw — glina i koło garncarskie","title_en":"Pottery Fundamentals: Clay and the Potter’s Wheel","certificate_pl":"Ukończenie kursu teoretycznego: Garncarstwo od podstaw — glina i koło garncarskie","certificate_en":"Pottery Fundamentals: Clay and the Potter’s Wheel","description_pl":"12 lekcji garncarstwa od podstaw: rodzaje mas, glina i szamot, narzędzia i koło, projekt kubka z obliczeniem skurczu, formowanie, suszenie, biskwit, szkliwo i angoba, bezpieczna praca z piecem i pyłem, wady szkliwa, kontrola jakości oraz projekt końcowy. Kurs edukacyjny, wymaga praktyki pod okiem doświadczonego ceramika i nie nadaje uprawnień zawodowych."},{"slug":"gontarz","old_title_pl":"Gontarz — drewniane dachy","title_pl":"Gontarstwo od podstaw — drewniane pokrycia dachowe","title_en":"Wooden Shingle Roofing Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Gontarstwo od podstaw — drewniane pokrycia dachowe","certificate_en":"Wooden Shingle Roofing Fundamentals","description_pl":"12 lekcji o gontach drewnianych: typy pokryć, materiałoznawstwo, narzędzia, ocena włókien drewna, rysunek i spadek połaci, ekspozycja i zakłady, styki boczne, obróbki dachu, wentylacja, uszkodzenia, konserwacja tradycyjnego pokrycia, BHP pracy na wysokości i projekt ilościowo-kosztowy. Kurs edukacyjny, nie daje uprawnień dekarskich; prawdziwa praca wymaga projektu, właściwych zabezpieczeń i fachowego nadzoru."},{"slug":"introligator-tradycja","old_title_pl":"Introligator — oprawa książek ręcznie","title_pl":"Introligatorstwo od podstaw — ręczna oprawa książek","title_en":"Hand Bookbinding Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Introligatorstwo od podstaw — ręczna oprawa książek","certificate_en":"Hand Bookbinding Fundamentals","description_pl":"12 szczegółowych lekcji introligatorstwa: budowa książki, kierunek włókien papieru i tektury, narzędzia, folio i składki, szycie, oprawa twarda, diagnostyka grzbietu, kleje i materiały, konserwacja historycznych książek, przechowywanie, kosztorys i własny projekt notesu. Kurs poznawczy i praktyczny do ćwiczeń na nowych materiałach, nie nadaje formalnych uprawnień konserwatorskich."},{"slug":"kaletnik-tradycja","old_title_pl":"Kaletnik — torby, paski i portfele","title_pl":"Kaletnictwo od podstaw — torby, paski i portfele","title_en":"Leathercraft Fundamentals: Bags, Belts and Wallets","certificate_pl":"Ukończenie kursu teoretycznego: Kaletnictwo od podstaw — torby, paski i portfele","certificate_en":"Leathercraft Fundamentals: Bags, Belts and Wallets","description_pl":"Poznaj skóra i zamienniki, pracę z narzędziami (szydło, wykroje i okucia) i historię tego, jak powstawał portfel. Tradycja wciąż potrafi inspirować; kurs nie zastępuje nauki pod okiem fachowca."},{"slug":"kolodziej","old_title_pl":"Kołodziej — drewniane koła dawnych wozów","title_pl":"Kołodziejstwo od podstaw — drewniane koła dawnych wozów","title_en":"Wheelwrighting Fundamentals: Traditional Wooden Wheels","certificate_pl":"Ukończenie kursu teoretycznego: Kołodziejstwo od podstaw — drewniane koła dawnych wozów","certificate_en":"Wheelwrighting Fundamentals: Traditional Wooden Wheels","description_pl":"16 pogłębionych lekcji o rzemiośle kołodziejskim: budowa i elementy koła, dobór gatunków drewna, obliczenia geometrii, talerzowatość, tradycyjne narzędzia, piasta i czopy, szprychy i dzwona, obręcz metalowa, traveler, oś i obciążenia, bicie boczne i promieniowe, konserwacja, renowacja, kosztorys i końcowy projekt pokazowego koła. Kurs teoretyczno-projektowy, nie nadaje uprawnień do wykonania kół do pojazdów użytkowych ani do prac kowalskich."},{"slug":"kowal-tradycja","old_title_pl":"Kowal — ogień, stal i tradycja kuźni","title_pl":"Kowalstwo od podstaw — ogień, stal i tradycja kuźni","title_en":"Traditional Blacksmithing and Forge Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Kowalstwo — od podstaw do projektu","certificate_en":"Traditional Blacksmithing and Forge Fundamentals","description_pl":"Poznaj pracę kowala: rysunek techniczny, stale, narzędzia, techniki kucia i przygotowanie projektu. Praktykę wykonuj pod okiem mistrza w warsztacie."},{"slug":"ludwisarz","old_title_pl":"Ludwisarz — dzwony i tradycyjne odlewnictwo","title_pl":"Ludwisarstwo od podstaw — dzwony i tradycyjne odlewnictwo","title_en":"Bellfounding and Traditional Casting Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Ludwisarstwo od podstaw — dzwony i tradycyjne odlewnictwo","certificate_en":"Bellfounding and Traditional Casting Fundamentals","description_pl":"Poznaj brąz i formy, pracę z narzędziami (model dzwonu i forma odlewnicza) i historię tego, jak powstawał dzwon. Tradycja wciąż potrafi inspirować; kurs nie zastępuje nauki pod okiem fachowca."},{"slug":"mlynarz-tradycyjny","old_title_pl":"Młynarz — od ziarna do mąki","title_pl":"Młynarstwo od podstaw — od ziarna do mąki","title_en":"Traditional Milling Fundamentals: From Grain to Flour","certificate_pl":"Ukończenie kursu teoretycznego: Młynarstwo od podstaw — od ziarna do mąki","certificate_en":"Traditional Milling Fundamentals: From Grain to Flour","description_pl":"12 lekcji tradycyjnego młynarstwa: budowa ziarna, przygotowanie i czyszczenie surowca, para kamieni młyńskich, koło wodne i przekładnie, rowki furrows, wyciąg mąki, odsiewanie, popiół, zagrożenie pyłem, magazynowanie, kontrola parametrów mąki, diagnostyka, bilans masowy oraz projekt końcowy. Kurs edukacyjny, nie zastępuje szkolenia stanowiskowego ani uprawnień do obsługi czynnego młyna."},{"slug":"plecionkarz","old_title_pl":"Plecionkarz — kosze z wikliny","title_pl":"Plecionkarstwo od podstaw — kosze z wikliny","title_en":"Traditional Willow Basket Weaving","certificate_pl":"Ukończenie kursu teoretycznego: Plecionkarstwo od podstaw — kosze z wikliny","certificate_en":"Traditional Willow Basket Weaving","description_pl":"Dobór i przygotowanie wikliny, budowa kosza, geometria, przeploty, uchwyty i kontrola jakości. Zadania na makietach obejmują kosztorys i dopasowanie kosza do konkretnego miejsca."},{"slug":"powroznik","old_title_pl":"Powroźnik — tradycyjne liny i powrozy","title_pl":"Powroźnictwo od podstaw — tradycyjne liny i powrozy","title_en":"Traditional Ropemaking Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Powroźnictwo od podstaw — tradycyjne liny i powrozy","certificate_en":"Traditional Ropemaking Fundamentals","description_pl":"12 lekcji powroźnictwa: włókno, przędza, pasmo i lina, konopie/len/sizal/manila, skręt S/Z, tradycyjna ropewalk, pomiary długości i skoku, konstrukcje skręcane i plecione, rozpoznawanie uszkodzeń, zakończenia, siła zrywająca i ograniczenia użycia, przechowywanie oraz projekt demonstracyjny. Kurs edukacyjny nie upoważnia do wykonywania lin do dźwigania, zabezpieczenia ludzi ani transportu."},{"slug":"rymarz","old_title_pl":"Rymarz — skórzane uprzęże i naprawy","title_pl":"Rymarstwo od podstaw — uprzęże i wyroby skórzane","title_en":"Saddlery and Harness Making Fundamentals","certificate_pl":"Ukończenie kursu teoretycznego: Rymarstwo od podstaw — uprzęże i wyroby skórzane","certificate_en":"Leather Harness Making and Repair Fundamentals","description_pl":"Poznaj skóra i okucia, pracę z narzędziami (szydło, igły, szablony) i historię tego, jak powstawał uprząż. Tradycja wciąż potrafi inspirować; kurs nie zastępuje nauki pod okiem fachowca."},{"slug":"kierownik-budowy","old_title_pl":"Lepszy kierownik budowy — decyzje, ludzie i plan","title_pl":"Organizacja budowy — decyzje, zespół i harmonogram","title_en":"Construction Site Organisation: Decisions, Teams and Scheduling","certificate_pl":"Organizacja i zarządzanie procesem budowlanym","certificate_en":"Construction Process Planning and Management","description_pl":"Kurs edukacyjny o organizacji budowy, dokumentacji, jakości, harmonogramie i komunikacji. Ukończenie kursu nie nadaje uprawnień budowlanych."},{"slug":"manhattan-active-wms","old_title_pl":"Manhattan ActiveWarehouse — obsługa magazynu WMS","title_pl":"Manhattan Active Warehouse Management — procesy magazynowe","title_en":"Manhattan Active Warehouse Management: Warehouse Processes","certificate_pl":"Ukończenie szkolenia: Manhattan Active Warehouse Management — procesy magazynowe","certificate_en":"Manhattan Active Warehouse Management: Warehouse Processes","description_pl":"Manhattan Active Warehouse Management: stany, receiving, wave, picking, slotting, labor, yard, robotyka i wysyłki."},{"slug":"oracle-wms-cloud","old_title_pl":"Oracle Warehouse Management Cloud — kompletny kurs WMS","title_pl":"Oracle Warehouse Management Cloud — procesy magazynowe","title_en":"Oracle Warehouse Management Cloud: Warehouse Processes","certificate_pl":"Ukończenie szkolenia: Oracle Warehouse Management Cloud — procesy magazynowe","certificate_en":"Oracle Warehouse Management Cloud: Warehouse Processes","description_pl":"Oracle WMS Cloud od ASN i LPN, przez lokalizacje i wave picking, do pakowania i wysyłki."},{"slug":"sap-ewm-magazyn","old_title_pl":"SAP EWM — magazyn od pierwszego skanu do eksperta","title_pl":"SAP EWM — od pierwszego skanu do obsługi procesów magazynowych","title_en":"SAP EWM: From the First Scan to Warehouse Operations","certificate_pl":"Ukończenie szkolenia: SAP EWM — od pierwszego skanu do obsługi procesów magazynowych","certificate_en":"SAP EWM: From the First Scan to Warehouse Operations","description_pl":"Przyjęcia, handling unit, warehouse tasks, RF, kompletacja, wydanie, zapasy i monitor magazynu."},{"slug":"ciesla-przygotowanie-czeladnicze","old_title_pl":"Cieśla — przygotowanie do egzaminu czeladniczego","title_pl":"Ciesielstwo — przygotowanie teoretyczne do egzaminu czeladniczego","title_en":"Carpentry: Theory Preparation for the Journeyman Examination","certificate_pl":"Ukończenie kursu teoretycznego: przygotowanie do egzaminu cieśli","certificate_en":"Carpentry: Preparation for the Journeyman Examination","description_pl":"Niezależny kurs przygotowujący do części teoretycznej egzaminu czeladniczego w zawodzie cieśla. Egzamin organizuje właściwa izba rzemieślnicza. Ukończenie kursu nie daje świadectwa czeladniczego."}]$names$::jsonb;
 changes integer;
BEGIN
 IF EXISTS (
  SELECT 1 FROM jsonb_to_recordset(catalogue) AS p(slug text,old_title_pl text,title_pl text)
  LEFT JOIN public.ta_courses c ON c.slug=p.slug AND c.published
  WHERE c.slug IS NULL OR c.title_pl NOT IN (p.old_title_pl,p.title_pl)
 ) THEN RAISE EXCEPTION 'Unexpected starting name in the published catalogue'; END IF;
 UPDATE public.ta_courses c
 SET title_pl=p.title_pl,title_en=p.title_en,certificate_pl=p.certificate_pl,
     certificate_en=p.certificate_en,description_pl=p.description_pl
 FROM jsonb_to_recordset(catalogue) AS p(slug text,title_pl text,title_en text,certificate_pl text,certificate_en text,description_pl text)
 WHERE c.slug=p.slug AND c.published;
 GET DIAGNOSTICS changes=ROW_COUNT;
 IF changes <> jsonb_array_length(catalogue) THEN RAISE EXCEPTION 'Unexpected updated course count'; END IF;
END
$update_course_names$;
